  [inst_8 : TopologicalSpace H'] {H'' : Type uH''} [inst_9 : TopologicalSpace H''] {I : ModelWithCorners 𝕜 E H}
  {J : ModelWithCorners 𝕜 F H'} {K : ModelWithCorners 𝕜 G H''} {M : Type uM} [inst_10 : TopologicalSpace M]
  [inst_11 : ChartedSpace H M] {N : Type uN} [inst_12 : TopologicalSpace N] [inst_13 : ChartedSpace H' N] {P : Type uP}
  [inst_14 : TopologicalSpace P] [inst_15 : ChartedSpace H'' P] {n : WithTop ℕ∞} {f : M → N} {g : N → P} {x : M}
  {Ff : Type u_1} [inst_16 : NormedAddCommGroup Ff] [inst_17 : NormedSpace 𝕜 Ff] {Fg : Type u_2}
