    ∀ (hFS : ∀ (x : N), F x ∈ Set.range (denseTorusCurve α)),
      let x := dense_torus_curve_range_topologicalSpace α hα;
      have x_1 := dense_torus_curve_range_chartedSpace α hα;
      ContMDiff K (modelWithCornersSelf ℝ ℝ) (↑⊤) (Set.codRestrict F (Set.range (denseTorusCurve α)) hFS)

∀ (α : ℝ) (hα : Irrational α),
  let x := dense_torus_curve_range_topologicalSpace α hα;
  have x_1 := dense_torus_curve_range_chartedSpace α hα;
  IsManifold (modelWithCornersSelf ℝ ℝ) ↑⊤ ↑(Set.range (denseTorusCurve α))

∀ (α : ℝ) (hα : Irrational α),
  have x := dense_torus_curve_range_topologicalSpace α hα;
  Subtype.val = denseTorusCurve α ∘ ⇑(Homeomorph.symm (dense_torus_curve_range_homeomorph α hα))

∀ (α : ℝ) (hα : Irrational α),
  let x := dense_torus_curve_range_topologicalSpace α hα;
  let x_1 := dense_torus_curve_range_chartedSpace α hα;
  have x_2 := ⋯;
  Manifold.IsImmersion (modelWithCornersSelf ℝ ℝ)
    (ModelWithCorners.pi fun x => modelWithCornersSelf ℝ (EuclideanSpace ℝ (Fin 1))) (↑⊤) Subtype.val

∀ (α : ℝ) (hα : Irrational α) (x : ↑(Set.range (denseTorusCurve α))),
  let x_1 := dense_torus_curve_range_topologicalSpace α hα;
  let x_2 := dense_torus_curve_range_chartedSpace α hα;
  have x_3 := ⋯;
  Manifold.IsImmersionAtOfComplement ⋯.complement (modelWithCornersSelf ℝ ℝ)
    (ModelWithCorners.pi fun x => modelWithCornersSelf ℝ (EuclideanSpace ℝ (Fin 1))) (↑⊤) Subtype.val x

∀ {E : Type uE} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {H : Type uH} [inst_2 : TopologicalSpace H]
  {M : Type uM} [inst_3 : TopologicalSpace M] [inst_4 : ChartedSpace H M] {I : ModelWithCorners ℝ E H}
  [IsManifold I ⊤ M] [FiniteDimensional ℝ E] [inst_7 : T2Space M] [SigmaCompactSpace M] (p : M),
  have U := { carrier := {x | x ≠ p}, is_open' := ⋯ };
  ∃ h, (∀ (x : ↥U), 0 < h x) ∧ Function.IsExhaustionFunction ⇑h

