  {M : Type uM} [inst_3 : TopologicalSpace M] [inst_4 : ChartedSpace H M] {I : ModelWithCorners ℝ E H}
  [IsManifold I ⊤ M] {E' : Type uE'} [inst_6 : NormedAddCommGroup E'] [inst_7 : NormedSpace ℝ E'] {H' : Type uH'}
  [inst_8 : TopologicalSpace H'] {J : ModelWithCorners ℝ E' H'} {S : Set M} [inst_9 : ChartedSpace H' ↑S]
  [IsManifold J ⊤ ↑S] [IsEmbeddedSubmanifold I J S] (p : ↑S), MDiffAt Subtype.val p
